{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import http from 'node:http';
import { mkdirSync } from 'node:fs';
import { dirname, extname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const root = dirname(fileURLToPath(import.meta.url));
const port = Number.parseInt(process.env.PORT || '8080', 10);
const dbPath = resolve(process.env.DB_PATH || join(root, 'data', 'workboard.sqlite'));
mkdirSync(dirname(dbPath), { recursive: true });

const db = new DatabaseSync(dbPath);
db.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
`);

const types = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8' };

function send(res, status, body, contentType = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': contentType, 'Cache-Control': 'no-store' });
  res.end(body);
}

async function readJson(req) {
  let body = '';
  for await (const chunk of req) body += chunk;
  return JSON.parse(body || '{}');
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  if (req.method === 'GET' && url.pathname === '/health') {
    return send(res, 200, JSON.stringify({ status: 'ok' }));
  }

  if (req.method === 'GET' && url.pathname === '/api/projects') {
    const projects = db.prepare('SELECT id, name FROM projects ORDER BY id ASC').all();
    return send(res, 200, JSON.stringify(projects));
  }

  if (req.method === 'POST' && url.pathname === '/api/projects') {
    try {
      const input = await readJson(req);
      const name = typeof input.name === 'string' ? input.name.trim() : '';
      if (!name) return send(res, 400, JSON.stringify({ error: 'Project name is required' }));
      const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      return send(res, 201, JSON.stringify({ id: Number(result.lastInsertRowid), name }));
    } catch {
      return send(res, 400, JSON.stringify({ error: 'Invalid request' }));
    }
  }

  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (req.method === 'GET' && projectMatch) {
    const project = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    return project ? send(res, 200, JSON.stringify(project)) : send(res, 404, JSON.stringify({ error: 'Project not found' }));
  }

  if (req.method === 'GET') {
    const relative = url.pathname === '/' ? 'index.html' : url.pathname.slice(1);
    const file = resolve(root, relative);
    if (file.startsWith(`${root}/`) || file === join(root, 'index.html')) {
      try {
        const { readFile } = await import('node:fs/promises');
        const content = await readFile(file);
        return send(res, 200, content, types[extname(file)] || 'application/octet-stream');
      } catch {
        // Unknown browser routes use the single page entry point.
      }
    }
    const { readFile } = await import('node:fs/promises');
    return send(res, 200, await readFile(join(root, 'index.html')), types['.html']);
  }

  return send(res, 404, JSON.stringify({ error: 'Not found' }));
});

server.listen(port, '0.0.0.0');
const content = document.querySelector('#content');

function element(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Request failed');
  return data;
}

function projectIdFromPath() {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  return match ? match[1] : null;
}

async function renderList() {
  content.replaceChildren();
  content.append(element('h1', '', 'Workboard'));

  const form = element('form', 'create-form');
  const field = element('div', 'field');
  const label = element('label', '', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  input.autocomplete = 'off';
  field.append(label, input);
  const submit = element('button', '', 'Create project');
  submit.type = 'submit';
  form.append(field, submit);
  const alert = element('p', 'alert');
  alert.hidden = true;
  alert.setAttribute('role', 'alert');
  content.append(form, alert);

  const projects = await request('/api/projects');
  const title = element('h2', 'section-title', 'Projects');
  const list = element('div', 'project-list');
  if (projects.length === 0) {
    list.append(element('p', 'empty', 'No projects yet. Create one to get started.'));
  } else {
    for (const project of projects) {
      const row = element('div', 'project-row');
      row.dataset.testid = 'project-row';
      row.append(element('span', 'project-name', project.name));
      const open = element('button', '', 'Open project');
      open.type = 'button';
      open.addEventListener('click', () => navigate(`/projects/${project.id}`));
      row.append(open);
      list.append(row);
    }
  }
  content.append(title, list);

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    try {
      await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      await renderList();
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    }
  });
}

async function renderProject(id) {
  const project = await request(`/api/projects/${id}`);
  content.replaceChildren();
  const back = element('button', 'back-button', 'Projects');
  back.type = 'button';
  back.addEventListener('click', () => navigate('/'));
  content.append(back, element('h1', '', project.name));
}

function navigate(path) {
  history.pushState({}, '', path);
  render();
}

async function render() {
  try {
    const id = projectIdFromPath();
    if (id) await renderProject(id);
    else await renderList();
  } catch {
    content.replaceChildren(element('p', 'alert', 'Unable to load this page.'));
  }
}

window.addEventListener('popstate', render);
render();
