  <title>Workboard</title>
  <link rel="stylesheet" href="/style.css">
  <script type="module" src="/app.js"></script>
</head>
<body>
  <main class="app-shell">
    <header class="topbar">
      <a class="brand" href="/">Workboard</a>
    </header>
    <section id="content" class="content" aria-live="polite"></section>
  </main>
</body>
</html>
:root {
  color-scheme: light;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #202a36;
  background: #f3f6f8;
  font-synthesis: none;
}

* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; min-height: 100vh; }
.app-shell { min-height: 100vh; }
.topbar { height: 68px; display: flex; align-items: center; padding: 0 max(24px, calc((100vw - 920px) / 2)); background: #fff; border-bottom: 1px solid #e1e7eb; }
.brand { color: #172b3b; font-size: 20px; font-weight: 750; text-decoration: none; letter-spacing: -.04em; }
.content { width: min(760px, calc(100% - 40px)); margin: 62px auto; }
h1 { margin: 0 0 28px; color: #172b3b; font-size: clamp(28px, 5vw, 36px); letter-spacing: -.045em; }
.create-form { display: flex; align-items: end; gap: 12px; padding: 22px; background: #fff; border: 1px solid #e0e7eb; border-radius: 12px; box-shadow: 0 5px 18px #233c5010; }
.field { display: grid; gap: 8px; flex: 1; }
label { color: #4d5c69; font-size: 13px; font-weight: 650; }
input { width: 100%; min-height: 44px; padding: 0 12px; color: #202a36; background: #fff; border: 1px solid #cbd5dc; border-radius: 7px; font: inherit; }
input:focus { outline: 3px solid #bfded7; border-color: #29856f; }
button { min-height: 42px; padding: 0 16px; border: 0; border-radius: 7px; background: #176c5b; color: #fff; font: inherit; font-size: 14px; font-weight: 650; cursor: pointer; }
button:hover { background: #105747; }
button:focus-visible, a:focus-visible { outline: 3px solid #90cabc; outline-offset: 2px; }
.alert { margin: 14px 0 0; color: #a72e35; font-size: 14px; }
.section-title { margin: 34px 0 12px; color: #465563; font-size: 14px; font-weight: 700; }
.project-list { display: grid; gap: 10px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 72px; padding: 13px 16px 13px 20px; background: #fff; border: 1px solid #e0e7eb; border-radius: 10px; }
.project-name { overflow-wrap: anywhere; font-weight: 650; }
.empty { margin: 0; padding: 20px; color: #73818c; background: #fff; border: 1px dashed #cbd5dc; border-radius: 10px; }
.back-button { margin-bottom: 26px; background: #e4eeeb; color: #185b4e; }
.back-button:hover { background: #d6e7e2; }
@media (max-width: 540px) { .content { margin-top: 38px; } .create-form { align-items: stretch; flex-direction: column; } .create-form button { width: 100%; } .project-row { align-items: stretch; flex-direction: column; } .project-row button { align-self: flex-start; } }
